@OptIn(ExperimentalLayoutApi::class)
FlowRow(
    horizontalArrangement = Arrangement.spacedBy(16.dp),
    verticalArrangement = Arrangement.spacedBy(16.dp),
) {
    MonarchCard(
        modifier = Modifier.width(256.dp),
    ) {
        MonarchText(text = {{title}}, style = MonarchTextStyle.Subheading)
        MonarchText(text = {{descriptions.0}}, style = MonarchTextStyle.Caption)
        MonarchText(text = {{content}}, style = MonarchTextStyle.Body)
        MonarchButton(
            text = {{action.label}},
            onClick = {},
            modifier = Modifier.align(Alignment.End),
            variant = MonarchButtonVariant.{{action.variant|pascal}},
            size = MonarchButtonSize.{{action.size|pascal}},
        )
    }
    MonarchCard(
        modifier = Modifier.width(256.dp),
        elevated = true,
    ) {
        MonarchText(text = {{title}}, style = MonarchTextStyle.Subheading)
        MonarchText(text = {{descriptions.1}}, style = MonarchTextStyle.Caption)
        MonarchText(text = {{content}}, style = MonarchTextStyle.Body)
        MonarchButton(
            text = {{action.label}},
            onClick = {},
            modifier = Modifier.align(Alignment.End),
            variant = MonarchButtonVariant.{{action.variant|pascal}},
            size = MonarchButtonSize.{{action.size|pascal}},
        )
    }
    MonarchCard(
        modifier = Modifier.width(256.dp),
    ) {
        MonarchText(text = {{title}}, style = MonarchTextStyle.Subheading)
        MonarchText(text = {{descriptions.2}}, style = MonarchTextStyle.Caption)
        MonarchText(text = {{content}}, style = MonarchTextStyle.Body)
        MonarchButton(
            text = {{action.label}},
            onClick = {},
            modifier = Modifier.align(Alignment.End),
            variant = MonarchButtonVariant.{{action.variant|pascal}},
            size = MonarchButtonSize.{{action.size|pascal}},
        )
    }
}

